@props(['notification', 'index' => 0])
<article class="notification-item {{ empty($notification['read']) ? 'unread' : '' }}" data-notification data-index="{{ $index }}"><span class="notification-icon" aria-hidden="true">{{ str_contains(strtolower($notification['type']), 'reply') ? '↩' : (str_contains(strtolower($notification['type']), 'assign') ? '♙' : '◈') }}</span><div class="notification-message"><strong>{{ $notification['title'] }}</strong><small>{{ $notification['type'] }} · {{ $notification['time'] }}</small></div>@if (empty($notification['read']))<span class="unread-dot" aria-label="Unread"></span>@endif<button class="icon-button" data-action="mark-read" data-index="{{ $index }}" aria-label="Mark as read">✓</button></article>
